//! Compiles the capitalization-rate table from `scripts/sim/en_caprate.tsv`
//! (generated by `scripts/build/cap_rate.py`) into `data/en_caprate.bin`, bundled
//! via `include_bytes!`.
//!
//! Each entry is `(word, p_cap)` where `p_cap` is
//! `P(capitalized | the word is not at a sentence start)` over cased corpora.
//! The merge consults it to keep genuine proper-noun capitals ("John") while
//! reverting a tiny model's spurious mid-sentence capitals ("so Make").

use std::path::PathBuf;

fn main() {
    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let tsv_path = manifest_dir.join("../../scripts/sim/en_caprate.tsv");
    let out_path = manifest_dir.join("data/en_caprate.bin");

    let content = std::fs::read_to_string(&tsv_path)
        .unwrap_or_else(|e| panic!("read {}: {e}", tsv_path.display()));

    // Source rows are `word \t p_cap \t count`. Keep word + p_cap.
    let mut entries: Vec<(String, f32)> = Vec::new();
    for line in content.lines() {
        let mut cols = line.split('\t');
        let (Some(word), Some(pcap)) = (cols.next(), cols.next()) else {
            continue;
        };
        let word = word.trim();
        if word.is_empty() {
            continue;
        }
        let Ok(pcap) = pcap.trim().parse::<f32>() else {
            continue;
        };
        if !(0.0..=1.0).contains(&pcap) {
            continue;
        }
        entries.push((word.to_string(), pcap));
    }

    // Versioned payload: the loader rejects a mismatched version into its
    // empty-table fallback instead of misdecoding a future format.
    let n = entries.len();
    let payload = (lune_dict::caprate::CAPRATE_FORMAT_VERSION, entries);
    let bytes =
        bincode::serde::encode_to_vec(&payload, bincode::config::standard()).expect("encode");
    std::fs::write(&out_path, &bytes).expect("write bin");

    println!(
        "  ✓ en_caprate.bin: {} entries, {:.1} KB",
        n,
        bytes.len() as f64 / 1024.0
    );
}
